def normalizar_cabecalho(valor):
    return re.sub(r"\s+", " ", str(valor or "")).strip()


def converter_link(link):
    partes = urlparse(link)
    parametros = parse_qs(partes.query)
    fragmento = parse_qs(partes.fragment)

    if partes.hostname == "docs.google.com":
        match = re.search(r"/spreadsheets/d/([^/]+)", partes.path)

        # Links publicados usam /d/e/ e devem ser preservados.
        if match and match.group(1) != "e":
            if "/export" not in partes.path:
                gid = parametros.get("gid") or fragmento.get("gid")
                exportacao = {"format": "csv"}
                if gid:
                    exportacao["gid"] = gid[0]

                return (
                    "https://docs.google.com/spreadsheets/d/"
                    + match.group(1)
                    + "/export?"
                    + urlencode(exportacao)
                )

    if partes.hostname == "drive.google.com":
        match = re.search(r"/file/d/([^/]+)", partes.path)
        if match:
            return (
                "https://drive.google.com/uc?"
                + urlencode({
                    "export": "download",
                    "id": match.group(1),
                })
            )

        if partes.path == "/open" and parametros.get("id"):
            return (
                "https://drive.google.com/uc?"
                + urlencode({
                    "export": "download",
                    "id": parametros["id"][0],
                })
            )

    return link


def transformar_registros(cabecalhos, linhas):
    cabecalhos = [normalizar_cabecalho(v) for v in cabecalhos]
    faltantes = [c for c in COLUNAS if c not in cabecalhos]

    if faltantes:
        raise ValueError(
            "A base não contém estas colunas: " + ", ".join(faltantes)
        )

    resultado = []

    for numero, linha in enumerate(linhas, start=2):
        if not any(v is not None and str(v).strip() for v in linha):
            continue

        if len(linha) > len(cabecalhos):
            raise ValueError(
                f"A linha {numero} tem mais valores que o cabeçalho."
            )

        registro = {}

        for chave, valor in zip(cabecalhos, linha):
            if not chave:
                continue

            if isinstance(valor, (datetime.datetime, datetime.date)):
                valor = valor.strftime("%d/%m/%Y")
            elif valor is not None:
                valor = str(valor).strip() or None

            registro[chave] = valor

        if registro.get("UF"):
            registro["UF"] = registro["UF"].upper()

        if registro.get("PROJETO DE LEI"):
            resultado.append(registro)

    return resultado


def ler_conteudo(conteudo):
    # Arquivos XLSX são arquivos ZIP.
    if conteudo.startswith(b"PK"):
        from openpyxl import load_workbook

        workbook = load_workbook(
            io.BytesIO(conteudo),
            data_only=True,
            read_only=True,
        )
        try:
            for aba in workbook:
                linhas = aba.iter_rows(values_only=True)
                cabecalhos = next(linhas, ())
                normalizados = [
                    normalizar_cabecalho(v) for v in cabecalhos
                ]
                if set(COLUNAS).issubset(normalizados):
                    return transformar_registros(cabecalhos, linhas)

            raise ValueError(
                "Nenhuma aba do Excel contém as colunas esperadas."
            )
        finally:
            workbook.close()

    inicio = conteudo.lstrip()[:500].lower()
    if (
        inicio.startswith(b"<!doctype html")
        or inicio.startswith(b"<html")
        or b"<html" in inicio
    ):
        raise ValueError(
            "O Drive retornou uma página de acesso ou erro. "
            "Confira se a planilha pode ser lida sem login."
        )

    for codificacao in ("utf-8-sig", "cp1252", "latin1"):
        try:
            texto = conteudo.decode(codificacao)
        except UnicodeDecodeError:
            continue

        for separador in (",", ";", "\t", "|"):
            leitor = csv.reader(
                io.StringIO(texto),
                delimiter=separador,
                strict=True,
            )
            try:
                cabecalhos = next(leitor, [])
                normalizados = [
                    normalizar_cabecalho(v) for v in cabecalhos
                ]
                if set(COLUNAS).issubset(normalizados):
                    return transformar_registros(cabecalhos, leitor)
            except csv.Error as erro:
                raise ValueError(
                    f"O CSV possui um erro de estrutura: {erro}"
                ) from erro

    raise ValueError(
        "Não foi possível ler a base como CSV ou XLSX "
        "com as colunas esperadas."
    )


def carregar_dados():
    link = DATA_SOURCE.strip()

    if not link or link == "inserir link da planilha":
        raise ValueError(
            'Configure DATA_SOURCE no app.py: substitua '
            '"inserir link da planilha" pelo link da sua base.'
        )

        if urlparse(link).scheme not in ("https", "http"):
            arquivo = PASTA_APP / link

            if not arquivo.is_file():
                raise ValueError(
                    f"Planilha não encontrada: {arquivo.name}. "
                    "Confira se ela foi enviada ao GitHub."
                )

            return ler_conteudo(arquivo.read_bytes())

    requisicao = Request(
        converter_link(link),
        headers={"User-Agent": "Mozilla/5.0"},
    )

    try:
        with urlopen(requisicao, timeout=60) as resposta:
            conteudo = resposta.read()
    except Exception as erro:
        raise ValueError(
            "Não foi possível acessar a planilha online. "
            "Confira o link, a conexão e a permissão de leitura."
        ) from erro

    return ler_conteudo(conteudo)


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        caminho = unquote(urlparse(self.path).path)
        status = 200

        try:
            if caminho in ("/", "/index.html"):
                body = HTML.encode("utf-8")
                tipo = "text/html; charset=utf-8"

            elif caminho == "/app.js":
                body = JS.encode("utf-8")
                tipo = "text/javascript; charset=utf-8"

            elif caminho == "/estados.geojson":
                body = zlib.decompress(
                    base64.b64decode(MAPA_COMPACTADO)
                )
                tipo = "application/json; charset=utf-8"

            elif caminho == "/dados.json":
                tipo = "application/json; charset=utf-8"
                try:
                    dados = carregar_dados()
                    body = json.dumps(
                        dados, ensure_ascii=False
                    ).encode("utf-8")
                except Exception as erro:
                    print("Erro na fonte de dados:", erro)
                    status = 503
                    body = json.dumps(
                        {"error": str(erro)},
                        ensure_ascii=False,
                    ).encode("utf-8")

            elif caminho.startswith("/assets/"):
                raiz = PASTA_ASSETS.resolve()
                arquivo = (
                    raiz / caminho[len("/assets/"):]
                ).resolve()

                if not arquivo.is_relative_to(raiz):
                    self.send_error(403)
                    return

                if not arquivo.is_file():
                    self.send_error(404)
                    return

                body = arquivo.read_bytes()
                tipo = (
                    mimetypes.guess_type(arquivo.name)[0]
                    or "application/octet-stream"
                )

            else:
                self.send_error(404)
                return

        except Exception as erro:
            print("Erro no servidor:", erro)
            self.send_error(500)
            return

        self.send_response(status)
        self.send_header("Content-Type", tipo)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

def main():
    import os

    parser = argparse.ArgumentParser(
        description="Dashboard de PLs sobre cannabis"
    )
    parser.add_argument(
        "--porta",
        type=int,
        default=int(os.environ.get("PORT", "8050")),
    )
    parser.add_argument("--sem-navegador", action="store_true")
    args = parser.parse_args()

    no_render = os.environ.get("RENDER") == "true"
    host = "0.0.0.0" 

    try:
        server = ThreadingHTTPServer(
            (host, args.porta),
            Handler,
        )
    except OSError as erro:
        parser.exit(1, f"Não foi possível iniciar: {erro}\n")

    print(f"Servidor iniciado em {host}:{args.porta}", flush=True)

    if not no_render and not args.sem_navegador:
        url = f"http://127.0.0.1:{args.porta}"
        threading.Timer(
            0.7,
            lambda: webbrowser.open(url),
        ).start()

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nDashboard encerrado.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()